/**
 * ToolCommandMcpAdapter - Register ToolCommands as MCP tools
 *
 * ARCHITECTURE DOCUMENTATION
 * ==========================
 *
 * This adapter bridges ToolCommands to the MCP (Model Context Protocol) server.
 * It auto-generates Zod schemas from ToolCommand metadata and registers each
 * ToolCommand as an MCP tool that AI assistants can invoke.
 *
 * KEY CONCEPTS:
 * - Converts IToolCommandArgument/IToolCommandFlag to Zod schemas
 * - Creates MCP tools with proper inputSchema definitions
 * - Handles session management for server-based commands
 * - Converts IToolCommandResult to MCP CallToolResult
 *
 * RELATED FILES:
 * - MinecraftMcpServer.ts: Where this adapter is used
 * - IToolCommand.ts: Source command definitions
 * - IToolCommandContext.ts: Session context handling
 */

import { z, ZodRawShape } from "zod";
import { CallToolResult } from "@modelcontextprotocol/sdk/types.js";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { ToolCommandRegistry } from "./ToolCommandRegistry";
import type { IToolCommand } from "./IToolCommand";
import { ToolCommandScope } from "./IToolCommand";
import type { IToolCommandArgument, IToolCommandFlag } from "./IToolCommandArgument";
import type { IToolCommandContext, IToolCommandOutput } from "./IToolCommandContext";
import { ToolCommandContextFactory } from "./IToolCommandContext";
import CreatorTools from "../CreatorTools";
import ServerManager from "../../local/ServerManager";
import Log from "../../core/Log";

/**
 * Map a type string to a base Zod schema (before optional/description).
 */
function typeToBaseZod(type: string): z.ZodTypeAny {
  switch (type) {
    case "number":
      return z.number();
    case "boolean":
      return z.boolean();
    case "stringArray":
      return z.array(z.string());
    case "string":
    case "path":
    case "identifier":
    case "choice":
    default:
      return z.string();
  }
}

/**
 * Convert a ToolCommand argument to a Zod schema.
 */
function argumentToZod(arg: IToolCommandArgument): z.ZodTypeAny {
  let schema = typeToBaseZod(arg.type).describe(arg.description);

  if (!arg.required) {
    schema = schema.optional();
  }

  return schema;
}

/**
 * Convert a ToolCommand flag to a Zod schema.
 */
function flagToZod(flag: IToolCommandFlag): z.ZodTypeAny {
  let schema = typeToBaseZod(flag.type).describe(flag.description);

  if (!flag.required) {
    schema = schema.optional();
  }

  return schema;
}

/**
 * Build a Zod input schema from ToolCommand metadata.
 */
function buildInputSchema(command: IToolCommand): ZodRawShape {
  const shape: ZodRawShape = {};

  // Add positional arguments
  if (command.metadata.arguments) {
    for (const arg of command.metadata.arguments) {
      shape[arg.name] = argumentToZod(arg);
    }
  }

  // Add flags
  if (command.metadata.flags) {
    for (const flag of command.metadata.flags) {
      shape[flag.name] = flagToZod(flag);
    }
  }

  // If command requires session (Minecraft), add sessionName parameter
  if (command.metadata.requiresMinecraft) {
    shape.sessionName = z.string().describe("Name of the Minecraft session to use");
  }

  return shape;
}

/**
 * Create an output writer that collects messages for MCP response.
 */
function createMcpOutput(): IToolCommandOutput & { messages: string[] } {
  const messages: string[] = [];
  return {
    messages,
    info: (msg) => messages.push(msg),
    success: (msg) => messages.push(`✓ ${msg}`),
    warn: (msg) => messages.push(`⚠ ${msg}`),
    error: (msg) => messages.push(`✗ ${msg}`),
    debug: (msg) => messages.push(`  ${msg}`),
    progress: (current, total, msg) => {
      if (total <= 0) {
        return;
      }
      const pct = Math.round((current / total) * 100);
      messages.push(`[${pct}%] ${msg || ""}`);
    },
  };
}

/**
 * Create an MCP tool handler function for a ToolCommand.
 */
function createMcpHandler(
  command: IToolCommand,
  creatorTools: CreatorTools,
  serverManager: ServerManager | undefined
): (args: Record<string, unknown>) => Promise<CallToolResult> {
  return async (args: Record<string, unknown>): Promise<CallToolResult> => {
    const output = createMcpOutput();

    // Extract sessionName if present, without mutating the original args
    const { sessionName: rawSessionName, ...commandArgs } = args;
    const sessionName = rawSessionName as string | undefined;

    // Build context
    // Note: In MCP context, we don't have an IMinecraft wrapper for DedicatedServer.
    // Commands that need server access should use context.session.serverManager.getActiveServer()
    // For now, pass undefined for minecraft - the session provides server access
    const context: IToolCommandContext = ToolCommandContextFactory.createSessionContext(
      creatorTools,
      { sessionName: sessionName ?? "default", serverManager, slot: 0 },
      undefined, // No IMinecraft adapter available in MCP context
      output,
      "mcp"
    );

    // Convert args object to positional array and flags
    const positionalArgs: string[] = [];
    const flags: Record<string, string | boolean | string[]> = {};

    if (command.metadata.arguments) {
      for (const argDef of command.metadata.arguments) {
        const value = commandArgs[argDef.name];
        if (value !== undefined) {
          positionalArgs.push(String(value));
        }
      }
    }

    if (command.metadata.flags) {
      for (const flagDef of command.metadata.flags) {
        const value = commandArgs[flagDef.name];
        if (value !== undefined) {
          flags[flagDef.name] = value as string | boolean | string[];
        }
      }
    }

    try {
      const result = await command.execute(context, positionalArgs, flags);

      // Build response text
      let responseText = "";
      if (output.messages.length > 0) {
        responseText = output.messages.join("\n");
      }
      if (result.message) {
        responseText += (responseText ? "\n" : "") + result.message;
      }
      if (!result.success && result.error) {
        responseText += (responseText ? "\n" : "") + `Error: ${result.error?.message || String(result.error)}`;
      }

      return {
        content: [{ type: "text", text: responseText || "Command completed" }],
        structuredContent: result.data ? { data: result.data } : undefined,
      };
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      Log.error(`ToolCommand MCP handler error for ${command.metadata.name}: ${message}`);
      return {
        content: [{ type: "text", text: `Error executing command: ${message}` }],
      };
    }
  };
}

/**
 * Register all ToolCommands that support MCP scope as MCP tools.
 *
 * @param mcpServer The MCP server to register tools on
 * @param creatorTools The CreatorTools instance
 * @param serverManager Optional ServerManager for session-based commands
 */
export function registerToolCommandsAsMcpTools(
  mcpServer: McpServer,
  creatorTools: CreatorTools,
  serverManager?: ServerManager
): void {
  const registry = ToolCommandRegistry.instance;
  const commands = registry.getAll(ToolCommandScope.mcp);

  Log.debug(`Registering ${commands.length} ToolCommands as MCP tools`);

  for (const command of commands) {
    const inputShape = buildInputSchema(command);
    const handler = createMcpHandler(command, creatorTools, serverManager);

    // Build title from command name and category
    const title = `${command.metadata.category}: ${command.metadata.name}`;

    // Build description with examples
    let description = command.metadata.description;
    if (command.metadata.examples && command.metadata.examples.length > 0) {
      description += `\n\nExamples:\n${command.metadata.examples.map((e) => `  ${e}`).join("\n")}`;
    }

    try {
      mcpServer.registerTool(
        `toolcmd_${command.metadata.name}`,
        {
          title,
          description,
          inputSchema: inputShape,
        },
        handler
      );

      Log.verbose(`Registered MCP tool: toolcmd_${command.metadata.name}`);
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      Log.error(`Failed to register MCP tool for ${command.metadata.name}: ${message}`);
    }
  }
}
